// CSD_RATIONALE_BEGIN
// Attempt 48: Retain attempt 43's proven structure (52% accuracy, 99% syntax) with
// ONE targeted change: delay the IsCompletePrefix early-close until at least 15
// constrained tokens have been generated.
//
// Root cause of attempt 43's 48% failure (141 semantic mismatches):
//   The average SQL query was only ~9.86 tokens. A minimal valid SQL such as
//   "SELECT city FROM employee" (4-5 tokens) satisfies IsCompletePrefix and
//   immediately closes the span, preventing WHERE/JOIN/GROUP BY/HAVING/ORDER BY
//   generation. The model needed these clauses for 141 questions but the strategy
//   always closed as soon as the parser first accepted the prefix.
//
// Fix: Add |currentConstrainedOut| >= 15 guard to the IsCompletePrefix early-close
//   branch. When the span is complete but short (<15 tokens), fall through to
//   GroupBoostedConstrainedStep instead. The group boost (6.0) makes schema-keyword
//   continuation tokens (WHERE, JOIN, GROUP, ORDER) more attractive than EOS,
//   encouraging the model to extend the query with the necessary clauses.
//   EOS-triggered close is unchanged: if the model chooses EOS from a complete
//   prefix, we still close immediately (model wants to stop → accept it).
//
// Preserved from attempt 43 (do NOT regress):
//   - 5-step preamble (lets model emit "SQL: " prefix)
//   - Force-open Phase 2 (always ensures << even if model doesn't emit it)
//   - GroupBoostedConstrainedStep with boost=6.0
//   - CloseSpanWithinBudget Phase 4 with budget ≤ 80
//   - RenderedEndsWith (not next == "<<") for delimiter detection
//
// Guidance: Add explicit "COMPLETE" and enumerate all necessary SQL clauses.
//   Remove the "no aliases" restriction that caused attempt 47 to regress to 41.3%.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble):
//   EOS path: insideConstrainedOut stays false → implication vacuously true.
//   Non-EOS path: generated grows by 1; when RenderedEndsWith("<<") fires we set
//     currentConstrainedOut := [] which satisfies IsValidPrefix([]) by precondition.
//   All other iterations leave state unchanged.
//
// Phase 2 (OpenConstrainedSpan):
//   Only runs when !insideConstrainedOut. Helper sets currentConstrainedOut := [];
//   IsValidPrefix([]) holds by precondition. insideConstrainedOut becomes true. ✓
//
// Phase 3 main loop (key change: enoughTokens guard):
//   (a) enoughTokens && IsCompletePrefix: CloseConstrainedSpan sets
//       insideConstrainedOut := false → implication vacuously true;
//       currentConstrainedOut := []. ✓
//   (b) !enoughTokens || !IsCompletePrefix (normal step): GroupBoostedConstrainedStep
//       hard-masks to parser-valid tokens plus EOS. If non-EOS next, AppendConstrainedToken
//       extends currentConstrainedOut by one valid token, preserving IsValidPrefix by
//       the parser extension contract. If EOS and IsCompletePrefix, CloseConstrainedSpan
//       is called → insideConstrainedOut false (vacuous). If EOS and !IsCompletePrefix,
//       break without mutation; invariant preserved from last loop state. ✓
//
// Phase 4 (CloseSpanWithinBudget):
//   Postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep increments steps by 1, appends ≤1 token (0 on EOS,
//   1 on non-EOS). Per-iteration invariant preserved.
// Phase 2: OpenConstrainedSpan increments steps by 1, appends exactly 1 "<<".
//   Net 1 token per 1 step. ✓
// Phase 3:
//   (a) IsCompletePrefix close: steps += 1; CloseConstrainedSpan appends ≤1 ">>". ≤1:1. ✓
//   (b) Normal step: steps += 1 (GroupBoostedConstrainedStep); AppendConstrainedToken
//       appends 1 token. 1:1. ✓
//   (c) EOS+close: steps += 1 (EOS) then +1 (close); generated grows ≤1 (">>"). ≤1:2. ✓
//   (d) EOS+no-close: steps += 1; no append. 0:1. ✓
//   In all branches maxSteps - steps decreases strictly (steps increments by ≥1 before
//   any break), so the decreases clause is satisfied.
// Phase 4: CloseSpanWithinBudget postcondition |generatedOut| <= |generated| + budget;
//   steps increases by closeBudget ≤ min(remaining, 80) ≤ remaining. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid and COMPLETE SQL SELECT statement using ONLY the exact table and column names from the provided schema. Include all necessary WHERE, JOIN, GROUP BY, HAVING, and ORDER BY clauses required by the question. The SQL must be placed between << and >>. No explanation, no markdown.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if model did not emit it naturally
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard parser control with schema-token group boosting.
// KEY CHANGE from attempt 43: Only allow IsCompletePrefix early-close after >= 15
// constrained tokens. When complete but short, fall through to GroupBoostedConstrainedStep
// so the model can add WHERE / JOIN / GROUP BY / HAVING / ORDER BY as needed.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var enoughTokens := |currentConstrainedOut| >= 15;
  if enoughTokens && parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

